import{_ as r,a0 as s,w as a,s as m,ao as l,I as e,x as n,a1 as o,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux桌面上的小饼饼，让启动应用分外不同！ | LCTT x X-CMD","titleTemplate":false,"description":"Linux桌面上的小饼饼，让启动应用分外不同！ | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux桌面上的小饼饼，让启动应用分外不同！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux桌面上的小饼饼，让启动应用分外不同！ | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/How to launch applications differently with Gnome-Pie on Linux desktop","title":"Linux桌面上的小饼饼，让启动应用分外不同！","tag":"201406","desc":""},"relativePath":"201406/How to launch applications differently with Gnome-Pie on Linux desktop.md","filePath":"[post].md"}'),u={name:"201406/How to launch applications differently with Gnome-Pie on Linux desktop.md"};function d(f,t,g,x,P,T){const i=s("Link");return a(),m("div",null,[t[15]||(t[15]=l(`<h1 id="linux桌面上的小饼饼-让启动应用分外不同" tabindex="-1">Linux桌面上的小饼饼，让启动应用分外不同！ <a class="header-anchor" href="#linux桌面上的小饼饼-让启动应用分外不同" aria-label="Permalink to “Linux桌面上的小饼饼，让启动应用分外不同！”">​</a></h1><p>最近，你能听到很多关于Ubuntu新的Unity界面的抱怨。我记得，当Unity开始兴起的时候，我正好离开Archlinux。然而，Unity间接地导致了一个后果：随着人们对它不满意，人们开始关注其他的桌面环境和Linux发行版。而如果你的系统支持Unity，没有人会反对将它弄得更顺眼些。</p><p>所以今天我向你推荐一个绝对原创的程序启动器： Gnome-Pie。你们可能会认为他的灵感来自魔兽世界插件&quot;OPie&quot;。因为他们有着相似的概念： 键盘快捷方式可以打开圆形&quot;菜单&quot;，您可以从中选择一个应用程序或命令来启动。这种设计背后的主要思想是用户不必记住命令，但需要记住他的方向和操作。它的饼形设计让指针可以用同样的距离启动每个应用程序。再加上我们还有如此多自定义组合键，极大的提高效率并且最大限度地实现了人机工程学。</p><h3 id="安装gnome-pie" tabindex="-1">安装Gnome-Pie <a class="header-anchor" href="#安装gnome-pie" aria-label="Permalink to “安装Gnome-Pie”">​</a></h3><p>在Ubuntu上，Gnome-Pie 可以从universe仓库中获得, 但是，某些原因，这个版本不是很稳定，常常会崩溃。作为一个备选方案，我建议你从官方的源进行下载。</p><pre><code>$ sudo add-apt-repository ppa:simonschneegans/testing
$ sudo apt-get update
$ sudo apt-get install gnome-pie 
</code></pre><p>在Fedora, 你可以使用以下命令：</p><pre><code>$ sudo yum install gnome-pie 
</code></pre>`,8)),e("p",null,[t[1]||(t[1]=n("对于Archlinux, 你可以在",-1)),o(i,{href:"https://aur.archlinux.org/packages/gnome-pie/"},{default:p(()=>[...t[0]||(t[0]=[n("AUR",-1)])]),_:1}),t[2]||(t[2]=n("找到它。",-1))]),t[16]||(t[16]=l('<h3 id="gnome-pie的基本用法" tabindex="-1">Gnome-Pie的基本用法 <a class="header-anchor" href="#gnome-pie的基本用法" aria-label="Permalink to “Gnome-Pie的基本用法”">​</a></h3><p>默认的，Gnome-Pie有一个比较可靠的初始配置。首先，你可以使用 <strong>Ctrl + Alt + a</strong> 调出，它将显示你的系统的基本应用程序。</p><p><img src="https://farm3.staticflickr.com/2917/14040269128_6dc6544c14_z.jpg" alt=""></p><p>接下来， 按下 <strong>Ctrl+Alt+b</strong> 调出第二个圆，这将显示你的文件管理器的书签。</p><p><img src="https://farm3.staticflickr.com/2903/14040269088_8de29edd18.jpg" alt=""></p><p>第三个，也许是最有用的，它会显示你的应用程序菜单，按下 <strong>Ctrl + Alt + 空格</strong> 可调出。</p><p><img src="https://farm3.staticflickr.com/2903/14040345657_071f40b22f_z.jpg" alt=""></p><p>第四个，仅用于控制音乐播放器。你可以猜到，快捷键是 <strong>Ctrl + Alt + m</strong>。</p><p><img src="https://farm3.staticflickr.com/2925/14226915065_8b0e3841c6_o.png" alt=""></p><p>第五个，你可以快速访问重新启动、 关机和注销命令 (<strong>Ctrl + Alt + q</strong>，我猜q是代表退出吧）。</p><p><img src="https://farm3.staticflickr.com/2931/14040303600_5b3a517335_o.png" alt=""></p><p>最后，第六个，你可以用Pie来控制窗口，可以最小化、 规模、 关闭， 等等. 并且，快捷键是 <strong>Ctrl+Alt+w</strong>。</p><p><img src="https://farm3.staticflickr.com/2904/14226699514_42d364a4d4_o.png" alt=""></p><p>虽然我发现这种默认设置已经是相当令人满意，几乎和预置的启动器一样好。然而，如果让我鸡蛋里找骨头，我会说一些快捷方式很难用一只手执行。大多数情况是，我们用两只手打开菜单，然后再回到鼠标以选择该选项。太不爽了。</p><p>然而，我们在用 Linux！谁会在乎默认设置？自定义才是王道。Gnome-Pie将为你提供优良的服务。通过配置，你可以编辑现有的Pie，改变程序图标，设计自己的Pie，改变主题，甚至将另外一个Pie菜单作为一个子菜单。</p>',15)),e("p",null,[o(i,{href:"https://www.flickr.com/photos/xmodulo/14247093043/"},{default:p(()=>[...t[3]||(t[3]=[e("img",{src:"https://farm6.staticflickr.com/5508/14247093043_1fe1188709_z.jpg",alt:""},null,-1)])]),_:1})]),t[17]||(t[17]=e("p",null,"你甚至可以编辑它来访问 URL、 自由设置热键、运行你自己的命令。惟一的缺憾可能是它缺少Widgets。",-1)),t[18]||(t[18]=e("p",null,[e("img",{src:"https://farm3.staticflickr.com/2927/14040264609_b7aa66f078_z.jpg",alt:""})],-1)),t[19]||(t[19]=e("p",null,"总之，相较于传统的基于文本的启动器，Gnome-Pie是一个相当有吸引力的可视化应用程序。我很喜欢他的自定义键盘和鼠标组合键，让我想起了我在War3或者LOL中的神级操作。如果玩家使用这种操作方式，它可以为你带来方便和高效。如果你想节约桌面空间，我甚至建议你不要将预置的启动器放到桌面上。总之，我甚至敢说它可以替代Gnome。",-1)),t[20]||(t[20]=e("p",null,"你觉得怎么样？你在所有相信世界上有这么好的东西吗？或者说，随着新的Gnome shell出现，Gnome-Pie开始失去竞争力？欢迎评论。",-1)),t[21]||(t[21]=e("hr",null,null,-1)),e("p",null,[t[5]||(t[5]=n("via: ",-1)),o(i,{href:"http://xmodulo.com/2014/05/launch-applications-differently-gnome-pie-linux-desktop.html"},{default:p(()=>[...t[4]||(t[4]=[n("http://xmodulo.com/2014/05/launch-applications-differently-gnome-pie-linux-desktop.html",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=n("译者：",-1)),o(i,{href:"https://github.com/MikeCoder"},{default:p(()=>[...t[6]||(t[6]=[n("MikeCoder",-1)])]),_:1}),t[9]||(t[9]=n(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=n("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原创翻译，",-1)),o(i,{href:"http://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[n("Linux中国",-1)])]),_:1}),t[14]||(t[14]=n(" 荣誉推出",-1))])])}const _=r(u,[["render",d]]);export{k as __pageData,_ as default};
